def downgrade() -> None:
    """只允许空回执库回退，已确认保存结果不能被迁移删除。"""
    op.execute("ALTER TABLE public.research_design_saves NO FORCE ROW LEVEL SECURITY")
    if op.get_bind().execute(sa.text("SELECT EXISTS(SELECT 1 FROM public.research_design_saves)")).scalar_one():
        raise ValueError("Design save receipts prevent destructive downgrade")
    # ### commands auto generated by Alembic - please adjust! ###
    op.drop_table('research_design_saves')
